'use server';

import { createClient } from '@/lib/supabase/server';
import { revalidatePath } from 'next/cache';
import { ActionResult } from '@/types/link';
import { z } from 'zod';

const createLinkSchema = z.object({
  url: z.string().url('올바른 URL을 입력하세요'),
  title: z.string().min(1, '제목을 입력하세요'),
  thumbnail_url: z.string().nullable().optional(),
  description: z.string().nullable().optional(),
  tags: z.array(z.string()).optional(),
  memo: z.string().nullable().optional(),
});

export async function createLink(
  input: z.infer<typeof createLinkSchema>
): Promise<ActionResult<{ id: string }>> {
  try {
    const validated = createLinkSchema.parse(input);
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
      return { success: false, error: '로그인이 필요합니다' };
    }

    const { data, error } = await supabase
      .from('links')
      .insert({
        user_id: user.id,
        url: validated.url,
        title: validated.title,
        thumbnail_url: validated.thumbnail_url ?? null,
        description: validated.description ?? null,
        tags: validated.tags ?? [],
        memo: validated.memo ?? null,
      })
      .select('id')
      .single();

    if (error) throw error;

    revalidatePath('/links');
    return { success: true, data: { id: data.id } };
  } catch (error) {
    if (error instanceof z.ZodError) {
      return { success: false, error: error.errors[0].message };
    }
    return { success: false, error: '링크 저장에 실패했습니다' };
  }
}

export async function deleteLink(id: string): Promise<ActionResult> {
  try {
    const supabase = await createClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
      return { success: false, error: '로그인이 필요합니다' };
    }

    const { error } = await supabase
      .from('links')
      .delete()
      .eq('id', id)
      .eq('user_id', user.id); // RLS backup

    if (error) throw error;

    revalidatePath('/links');
    return { success: true };
  } catch (error) {
    return { success: false, error: '링크 삭제에 실패했습니다' };
  }
}

