import ogs from 'open-graph-scraper';
import { LinkMetadata } from '@/types/link';

const TIMEOUT_MS = 10000; // 10 seconds
const ALLOWED_PROTOCOLS = ['http:', 'https:'];
const BLOCKED_HOSTS = [
  'localhost',
  '127.0.0.1',
  '0.0.0.0',
  '169.254.169.254', // AWS metadata
  '::1',
];

export async function fetchLinkMetadata(
  url: string
): Promise<{ success: true; data: LinkMetadata } | { success: false; error: string }> {
  try {
    // Validate URL
    const urlObj = new URL(url);

    if (!ALLOWED_PROTOCOLS.includes(urlObj.protocol)) {
      return { success: false, error: 'http/https URL만 지원합니다' };
    }

    if (BLOCKED_HOSTS.some(host => urlObj.hostname.includes(host))) {
      return { success: false, error: '내부망 주소는 사용할 수 없습니다' };
    }

    // Fetch with timeout
    const { result, error } = await Promise.race([
      ogs({ url, timeout: TIMEOUT_MS }),
      new Promise<never>((_, reject) =>
        setTimeout(() => reject(new Error('Timeout')), TIMEOUT_MS)
      ),
    ]);

    if (error || !result) {
      return { success: false, error: '메타데이터를 가져올 수 없습니다' };
    }

    const metadata: LinkMetadata = {
      title: result.ogTitle || result.twitterTitle || '',
      description: result.ogDescription || result.twitterDescription || null,
      thumbnail_url: result.ogImage?.[0]?.url || result.twitterImage?.[0]?.url || null,
    };

    if (!metadata.title) {
      return { success: false, error: '제목을 찾을 수 없습니다' };
    }

    return { success: true, data: metadata };
  } catch (error) {
    console.error('Metadata fetch error:', error);
    return { success: false, error: '메타데이터를 가져올 수 없습니다' };
  }
}

