export async function getLinks(filter?: LinkFilter) {
  const supabase = await createClient();
  const { data: { user } } = await supabase.auth.getUser();

  if (!user) return { data: null, error: 'Unauthorized' };

  let query = supabase
    .from('links')
    .select('*')
    .eq('user_id', user.id);

  // Text search: title OR memo OR tags (array contains)
  if (filter?.searchQuery) {
    const q = filter.searchQuery.toLowerCase();
    // Note: Postgres full-text search would be better for production
    query = query.or(
      `title.ilike.%${q}%,memo.ilike.%${q}%,tags.cs.{${q}}`
    );
  }

  // Tag filter (intersection: link must have ALL selected tags)
  if (filter?.selectedTags && filter.selectedTags.length > 0) {
    query = query.contains('tags', filter.selectedTags);
  }

  // Read status filter
  if (filter?.readStatus === 'read') {
    query = query.eq('is_read', true);
  } else if (filter?.readStatus === 'unread') {
    query = query.eq('is_read', false);
  }
  // 'all' → no filter

  // Favorite filter
  if (filter?.favoriteOnly) {
    query = query.eq('is_favorite', true);
  }

  const { data, error } = await query.order('created_at', { ascending: false });
  return { data, error };
}

