'use client';

import { useRouter, useSearchParams } from 'next/navigation';
import { useTransition, useState, useEffect } from 'react';
import { Input } from '@/components/ui/input';
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import { useDebouncedCallback } from 'use-debounce';

interface SearchFilterBarProps {
  availableTags: string[];
}

export function SearchFilterBar({ availableTags }: SearchFilterBarProps) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [isPending, startTransition] = useTransition();

  const [searchQuery, setSearchQuery] = useState(searchParams.get('q') || '');
  const selectedTag = searchParams.get('tag') || '';
  const readStatus = searchParams.get('read') || 'all';
  const favoriteOnly = searchParams.get('fav') === 'true';

  const updateParams = (updates: Record<string, string | null>) => {
    const params = new URLSearchParams(searchParams);

    Object.entries(updates).forEach(([key, value]) => {
      if (value === null || value === '' || value === 'all') {
        params.delete(key);
      } else {
        params.set(key, value);
      }
    });

    startTransition(() => {
      router.push(`/links?${params.toString()}`, { scroll: false });
    });
  };

  const debouncedSearch = useDebouncedCallback((value: string) => {
    updateParams({ q: value });
  }, 500);

  const handleSearchChange = (value: string) => {
    setSearchQuery(value);
    debouncedSearch(value);
  };

  const handleReset = () => {
    setSearchQuery('');
    router.push('/links');
  };

  return (
    <div className="flex flex-col md:flex-row gap-4 mb-6">
      <Input
        placeholder="제목, 메모, 태그 검색..."
        value={searchQuery}
        onChange={(e) => handleSearchChange(e.target.value)}
        className="flex-1"
      />

      <Select value={selectedTag} onValueChange={(v) => updateParams({ tag: v })}>
        <SelectTrigger className="w-40">
          <SelectValue placeholder="모든 태그" />
        </SelectTrigger>
        <SelectContent>
          <SelectItem value="">모든 태그</SelectItem>
          {availableTags.map(tag => <SelectItem key={tag} value={tag}>{tag}</SelectItem>)}
        </SelectContent>
      </Select>

      <Select value={readStatus} onValueChange={(v) => updateParams({ read: v })}>
        <SelectTrigger className="w-32">
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          <SelectItem value="all">전체</SelectItem>
          <SelectItem value="read">읽음</SelectItem>
          <SelectItem value="unread">안읽음</SelectItem>
        </SelectContent>
      </Select>

      <Button
        variant={favoriteOnly ? 'default' : 'outline'}
        onClick={() => updateParams({ fav: favoriteOnly ? null : 'true' })}
      >
        즐겨찾기만
      </Button>

      <Button variant="ghost" onClick={handleReset}>
        초기화
      </Button>
    </div>
  );
}

